/** Unified catalog and SDK summary shared across Cloudflare, Payload and VitePress. */
export const sdkSummary = () => {
  const base = catalogSummary(EXAMPLES)
  return {
    ...base,
    sdkCollections: SDK_COLLECTIONS,
    workerRoutes: WORKER_ROUTES,
    collections: {
      ...base.collections,
      computations: allComputations().length,
      standards: allStandards().length,
      clauses: allClauses().length,
    },
    tools: toolboxOfTool.size,
  }
}

/** Find one page of any Lean-configured SDK collection in Payload REST shape. */
export const sdkCollection = <C extends SdkCollection>(collection: C, page = 1, limit = 100): PayloadPaginated<SdkDocMap[C]> => {
  if ((CATALOG_COLLECTIONS as readonly string[]).includes(collection)) {
    const { phase: _p, collection: _c, ...found } = catalogSeeds(EXAMPLES, collection, page, limit)
    if (collection === 'products') {
      const docs = found.docs.map((d) => ({ ...d, vitepressPath: `/catalog/${d.id}` }))
      return { ...found, docs } as unknown as PayloadPaginated<SdkDocMap[C]>
    }
    return found as unknown as PayloadPaginated<SdkDocMap[C]>
  }
  if (collection === 'computations') return paginate(allComputations(), page, limit) as unknown as PayloadPaginated<SdkDocMap[C]>
  if (collection === 'standards') return paginate(allStandards(), page, limit) as unknown as PayloadPaginated<SdkDocMap[C]>
  if (collection === 'clauses') return paginate(allClauses(), page, limit) as unknown as PayloadPaginated<SdkDocMap[C]>
  throw new Error(`collection: ${SDK_COLLECTIONS.join(', ')}`)
}

/** Find one document by sealed UUID (or theorem key / slug / clause) in Payload REST shape. */
export const sdkFindById = <C extends SdkCollection>(collection: C, id: string): (PayloadRecord<SdkDocMap[C]> & Record<string, unknown>) | null => {
  if (collection === 'products') {
    try {
      const p = catalogProduct(EXAMPLES, id)
      return {
        id: p.product.id,
        ...p.product.data,
        vitepressPath: `/catalog/${p.product.id}`,
        variants: { docs: p.variants.map((v) => ({ id: v.id, ...v.data })), hasNextPage: false, totalDocs: p.variants.length },
        entanglements: p.entanglements.map((e) => ({
          targetTheorem: e.targetTheorem,
          targetProduct: e.targetProduct,
          direction: e.direction,
          variantId: e.variant.id,
          mcpTool: e.mcpTool,
        })),
        mcpTools: p.mcpTools,
      } as unknown as PayloadRecord<SdkDocMap[C]> & Record<string, unknown>
    } catch { return null }
  }
  if (collection === 'computations') {
    const hit = allComputations().find((c) => c.id === id || c.title === id || c.address === id || c.tool === id)
    return (hit ?? null) as (PayloadRecord<SdkDocMap[C]> & Record<string, unknown>) | null
  }
  if (collection === 'standards') {
    const hit = allStandards().find((s) => s.id === id || s.reference === id || slug(s.reference) === id)
    return (hit ?? null) as (PayloadRecord<SdkDocMap[C]> & Record<string, unknown>) | null
  }
  if (collection === 'clauses') {
    const hit = allClauses().find((c) => c.id === id || c.clause === id || slug(`${c.clause} ${c.name}`) === id)
    return (hit ?? null) as (PayloadRecord<SdkDocMap[C]> & Record<string, unknown>) | null
  }
  const summary = sdkSummary()
  const total = summary.collections[collection as CatalogCollection]
  if (collection === 'variants') {
    for (let page = 1; ; page++) {
      const batch = sdkCollection('variants', page, 500)
      const hit = batch.docs.find((d) => d.id === id)
      if (hit) return hit as unknown as PayloadRecord<SdkDocMap[C]> & Record<string, unknown>
      if (!batch.hasNextPage) return null
    }
  }
  const all = sdkCollection(collection, 1, Math.max(1, total))
  return (all.docs.find((d) => d.id === id) ?? null) as (PayloadRecord<SdkDocMap[C]> & Record<string, unknown>) | null
}

/** Execute any QPU MCP tool computation and return a sealed harmonized Payload + VitePress record. */
export const sdkCompute = async (tool: string, args: Record<string, unknown> = {}): Promise<PayloadRecord<ComputationData>> => {
  const reply = await Promise.resolve(handle(callEnvelope(tool, args))) as { result?: { structuredContent?: unknown }; error?: { message: string } }
  if (reply.error) throw new Error(reply.error.message)
  const toolbox = toolboxOfTool.get(tool) ?? 'flow'
  const address = uuid(`${tool}${canonicalText(args)}`)
  const data: ComputationData = {
    title: `${tool}:${address.slice(0, 8)}`,
    tool,
    toolbox,
    address,
    arguments: args,
    result: reply.result?.structuredContent,
    licence: LICENSE.spdx,
    standard: SDK_VOCABULARY,
    vitepressPath: `/mcp/${slug(toolbox)}`,
    mcpTool: { name: tool, arguments: args },
  }
  const doc = catalogDoc('computations', data)
  return { id: doc.id, ...doc.data }
}

