const cell = (text: string) => text.replace(/\|/g, '\\|').replace(/\s+/g, ' ')
const mdTable = (head: readonly string[], rows: readonly (readonly string[])[]) => [
  `| ${head.join(' | ')} |`,
  `|${head.map(() => '---').join('|')}|`,
  ...rows.map((row) => `| ${row.map(cell).join(' | ')} |`),
]

/** Typed VitePress dynamic routes built from the same catalog products, witnesses, entanglements and client MCP tools. */
export const sdkProductRoutes = (): VitePressRouteDoc<CatalogRouteParams>[] => THEOREMS.map((t) => {
  const p = catalogProduct(EXAMPLES, t.key)
  const facts: [string, string][] = [
    ['product', `\`${p.product.id}\``],
    ['theorem', `\`${t.key}\``],
    ['module', `\`${t.module}\``],
    ['examples', String(p.examples.length)],
    ['witnesses', String(p.witnesses.length)],
    ['entanglements', String(p.entanglements.length)],
    ['variants', String(p.variants.length)],
    ['mcpTools', String(p.mcpTools.length)],
    ['price', '0'],
    ['funding', LICENSE.donation],
    ['licence', LICENSE.spdx],
    ['document', `${SDK_API_PREFIX}/products/${p.product.id}`],
  ]
  const content = [
    '::: v-pre', '', ...mdTable(['', ''], facts), '', '```lean', t.statement, '```', '',
    ...(p.examples.length
      ? ['## examples', '', ...mdTable(['example', 'tool', 'address'], p.examples.map((e) => [`\`${e.example}\``, e.tool, `\`${e.address}\``])), '', '## variants', '', ...mdTable(['example', 'witness', 'variant', 'mcpTool', 'address'], p.witnessVariants.map((v) => [`\`${String(v.data.example)}\``, String(v.data.witness), `\`${v.id}\``, `\`${v.data.mcpTool.name}\``, `\`${String(v.data.address)}\``])), '']
      : []),
    ...(p.entanglements.length
      ? ['## entanglements', '', ...mdTable(['direction', 'theorem', 'product', 'mcpTool', 'rest'], p.entanglements.map((e) => [e.direction, `[${e.targetTheorem}](/catalog/${e.targetProduct})`, `\`${e.targetProduct}\``, `\`${e.mcpTool.name}\``, `\`${e.mcpTool.rest.path}\``])), '']
      : []),
    ':::', '',
  ].join('\n')
  return {
    params: {
      product: p.product.id,
      theorem: t.key,
      module: t.module,
      statement: t.statement,
      variants: String(p.variants.length),
      entanglements: String(p.entanglements.length),
    },
    content,
  }
})

