/** Execute one complete autonomous online pipeline cycle at the edge and return a sealed 122-qubit UUID receipt. */
export const runAutonomousPipeline = (origin = 'https://qpu.uuidna.com') => {
  const root = origin.replace(/\/+$/, '')
  const cap = quantumCapacity()
  const kem = kemRound({ algorithm: 'X-Wing' })
  const dsa = dsaRound({ algorithm: 'ML-DSA-65' }, `${SDK_VOCABULARY}:${root}`)
  const entangle = sdkInteract('Advantage.advantage_unbounded', 'Advantage.two_pow_le_space')
  const ui = payloadUiManifest(root)
  const enhanced = googleEnhance({
    api: 'qpu.pipeline',
    payload: { origin: root, version: VERSION, qubits: cap.register.free },
    theorem: 'Advantage.advantage_unbounded',
    targetTheorem: 'Advantage.two_pow_le_space',
  })
  const gqai = gqaiChallengeMatrix(root)
  const script = gqaiAppsScript(root)
  const stages = [
    { id: 'register', passed: cap.gate.holds && cap.full, evidence: `${cap.used}/${cap.register.free}` },
    { id: 'pqc-kem', passed: kem.agrees === true, evidence: String(kem.algorithm) },
    { id: 'pqc-dsa', passed: dsa.verified === true && dsa.refusesChanged === true, evidence: String(dsa.algorithm) },
    { id: 'entanglement', passed: entangle.entangled === true && entangle.direct === true, evidence: 'Advantage.advantage_unbounded' },
    { id: 'payload-ui', passed: ui.coverage.percent === 100, evidence: `${ui.coverage.used}/${ui.coverage.total}` },
    { id: 'google-apis', passed: enhanced.sealed === true && enhanced.sha256.length === 64, evidence: enhanced.handle },
    { id: 'gqai-challenges', passed: gqai.allWitnessesAccepted === true && gqai.sealed === true && script.sealed === true && gqai.challenges.every((c) => c.witnessesAccepted && c.baseline.evidenceStatus === 'supported'), evidence: gqai.handle },
  ]
  const passed = stages.filter((s) => s.passed).length
  const holds = passed === stages.length
  const canonical = canonicalText({ origin: root, version: VERSION, stages })
  const address = uuid(canonical)
  return {
    phase: 'pipeline-run' as const,
    autonomous: true as const,
    origin: root,
    version: VERSION,
    holds,
    passed,
    total: stages.length,
    address,
    handle: address.slice(0, 8),
    sha256: hex(sha256(utf8(canonical))),
    sealed: seal(address).valid,
    standard: SDK_VOCABULARY,
    licence: LICENSE.spdx,
    stages,
  }
}

/** Read one Lean-configured Payload Global via standard GET /api/globals/{slug}. */
export const sdkFindGlobal = (
  slug: SdkGlobal,
  origin = 'https://qpu.uuidna.com',
  params?: URLSearchParams,
): Record<string, unknown> => {
  const page = Number(params?.get('page') ?? '1')
  const limitRaw = params?.get('limit')
  const limit = limitRaw === null || limitRaw === undefined ? 100 : Number(limitRaw)
  if (slug === 'catalog') {
    if (params?.get('view') === 'seo') {
      return ecommerceSeoMcp({
        target: params.get('target') ?? undefined,
        tool: params.get('tool') ?? undefined,
        id: params.get('id') ?? undefined,
        limit: limitRaw === null || limitRaw === undefined ? undefined : limit,
      }, EXAMPLES, origin)
    }
    return sdkSummary()
  }
  if (slug === 'payload-ui') {
    if (params?.get('view') === 'rbac') return rbacAudit(origin)
    return payloadUiManifest(origin)
  }
  if (slug === 'pipeline') return pipelineManifest(origin)
  if (slug === 'clay-duality') return sdkClayDuality()
  if (slug === 'clay-1000bit') {
    if (params?.get('view') === 'research') return clay1000Research(origin)
    return sdkClay1000Bit(page, limitRaw === null || limitRaw === undefined ? 25 : limit)
  }
  if (slug === 'mcp-tools') {
    if (params?.get('view') === 'seo') {
      return ecommerceSeoMcp({
        toolsOnly: true,
        target: params.get('target') ?? undefined,
        limit: limitRaw === null || limitRaw === undefined ? undefined : limit,
      }, EXAMPLES, origin)
    }
    return sdkMcpTools(params?.get('product') ?? undefined, page, limit)
  }
  if (slug === 'google') {
    const view = params?.get('view')
    if (view === 'discovery') return googleDiscoveryDocument(origin)
    if (view === 'gemini-tools') return googleGeminiTools(params?.get('product') ?? undefined, limitRaw === null || limitRaw === undefined ? undefined : limit)
    if (view === 'openapi') return googleOpenapiDocument(origin)
    if (view === 'integrations') return googleIntegrations(origin)
    if (view === 'challenges') return gqaiChallengeMatrix(origin)
    if (view === 'apps-script') return gqaiAppsScript(origin)
    return {
      ...googleIntegrations(origin),
      discovery: googleDiscoveryDocument(origin),
      geminiTools: googleGeminiTools(params?.get('product') ?? undefined, limitRaw === null || limitRaw === undefined ? undefined : limit),
      openapi: googleOpenapiDocument(origin),
      challenges: gqaiChallengeMatrix(origin),
    }
  }
  throw new Error(`global: ${SDK_GLOBALS.join(', ')}`)
}

/** Update or trigger one Lean-configured Payload Global via standard POST /api/globals/{slug}. */
export const sdkUpdateGlobal = (
  slug: SdkGlobal,
  body: Record<string, unknown> = {},
  origin = 'https://qpu.uuidna.com',
): Record<string, unknown> => {
  if (slug === 'catalog' && (body.seo !== undefined || body.attach !== undefined || body.target !== undefined)) {
    return ecommerceSeoMcp(body.seo ?? body, EXAMPLES, origin)
  }
  if (slug === 'payload-ui' && (body.action === 'rbac-check' || typeof body.subject === 'string')) {
    return rbacCheck(body as Parameters<typeof rbacCheck>[0])
  }
  if (slug === 'pipeline') return runAutonomousPipeline(origin)
  if (slug === 'google') {
    if (body.action === 'verify-compilation' || typeof body.qubits === 'number') return verifyCompilationMetrics(body)
    return googleEnhance(body)
  }
  return sdkFindGlobal(slug, origin)
}

/** Whether a Cloudflare Worker request targets a standard Payload package REST route (collections or globals, excluding /api/mcp). */
export const isSdkRequest = (request: Request): boolean => {
  const path = new URL(request.url).pathname
  if (!path.startsWith(`${SDK_API_PREFIX}/`)) return false
  const parts = path.slice(SDK_API_PREFIX.length + 1).replace(/\/+$/, '').split('/').filter(Boolean)
  if (!parts.length || parts.length > 2) return false
  const [head, second] = parts
  if (head === 'mcp') return false
  if (head === 'globals') return Boolean(second && SDK_GLOBAL_SET.has(second))
  if (!SDK_COLLECTION_SET.has(head!)) return false
  return request.method !== 'POST' || !second
}

/** Cloudflare Worker fetch handler implementing standard Payload REST operations (collections and globals only; MCP stays on /api/mcp). */
export const serveSdk = async (request: Request): Promise<Response> => {
  if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: SDK_CORS_HEADERS })
  const url = new URL(request.url)
  const origin = url.origin
  const parts = url.pathname.slice(SDK_API_PREFIX.length + 1).replace(/\/+$/, '').split('/').filter(Boolean)
  const [head, rawSecond] = parts
  const second = rawSecond ? decodeURIComponent(rawSecond) : undefined
  const page = Number(url.searchParams.get('page') ?? '1')
  const limit = Number(url.searchParams.get('limit') ?? '100')
  try {
    if (request.method === 'GET') {
      if (head === 'globals' && second && SDK_GLOBAL_SET.has(second)) {
        return jsonResponse(sdkFindGlobal(second as SdkGlobal, origin, url.searchParams))
      }
      if (head && SDK_COLLECTION_SET.has(head)) {
        const col = head as SdkCollection
        if (!second) return jsonResponse(sdkCollection(col, page, limit))
        const found = sdkFindById(col, second)
        return found ? jsonResponse(found) : jsonResponse({ error: `not found: ${col}/${second}` }, 404)
      }
      return jsonResponse({ error: `unknown route: ${url.pathname}` }, 404)
    }
    if (request.method === 'POST') {
      const raw = await request.text()
      const body = raw.trim() ? JSON.parse(raw) as Record<string, unknown> : {}
      if (head === 'globals' && second && SDK_GLOBAL_SET.has(second)) {
        return jsonResponse(sdkUpdateGlobal(second as SdkGlobal, body, origin))
      }
      if (head === 'computations' && !second) {
        if (typeof body.source === 'string' && typeof body.target === 'string') {
          return jsonResponse(sdkInteract(body.source, body.target))
        }
        if (typeof body.tool === 'string') {
          const args = body.arguments && typeof body.arguments === 'object' ? body.arguments as Record<string, unknown> : {}
          return jsonResponse(await sdkCompute(body.tool, args))
        }
      }
      return jsonResponse({ error: `unsupported POST: ${url.pathname}` }, 405)
    }
    return jsonResponse({ error: `method ${request.method}` }, 405)
  } catch (error) {
    return jsonResponse({ error: error instanceof Error ? error.message : String(error) }, 400)
  }
}

/** Portable @payloadcms/sdk-shaped client over standard Payload REST collections, globals, and /api/mcp connector. */
export const createQpuSdk = (baseURL: string, fetcher: typeof fetch = fetch): PayloadSdkClient => {
  const root = baseURL.replace(/\/+$/, '')
  const api = (path: string) => `${root}${SDK_API_PREFIX}${path}`
  const readJson = async <T>(res: Response): Promise<T> => {
    const data = await res.json() as T & { error?: string | { message?: string } }
    if (!res.ok) throw new Error(typeof data.error === 'string' ? data.error : data.error?.message ?? `HTTP ${res.status}`)
    return data
  }
  const qs = (query?: Record<string, string | number>) => {
    if (!query) return ''
    const p = new URLSearchParams()
    for (const [k, v] of Object.entries(query)) p.set(k, String(v))
    const s = p.toString()
    return s ? `?${s}` : ''
  }
  return {
    create: async ({ collection, data }) => readJson<{ id: PayloadRelationId }>(await fetcher(api(`/${collection}`), { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(data) })),
    find: async ({ collection, page = 1, limit = 100 }) => readJson(await fetcher(api(`/${collection}?page=${page}&limit=${limit}`))),
    findByID: async ({ collection, id }) => readJson(await fetcher(api(`/${collection}/${encodeURIComponent(id)}`))),
    findGlobal: async ({ slug, query }) => readJson(await fetcher(api(`/globals/${encodeURIComponent(slug)}${qs(query)}`))),
    updateGlobal: async ({ slug, data }) => readJson(await fetcher(api(`/globals/${encodeURIComponent(slug)}`), { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(data) })),
    mcp: async (method, params = {}) => readJson(await fetcher(api('/mcp'), { method: 'POST', headers: { 'content-type': 'application/json', accept: 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }) })),
  }
}
